+
+function writeText(root, relPath, value) {
+  const target = resolvePath(root, relPath);
+  if (!target) throw new TypeError('root and relPath must be strings');
+  fs.mkdirSync(path.dirname(target), { recursive: true });
+  fs.writeFileSync(target, value.endsWith('\n') ? value : `${value}\n`, 'utf8');
+}
+
+function sha256File(root, relPath) {
+  const target = resolvePath(root, relPath);
+  if (!target || !fs.existsSync(target)) return null;
+  return crypto.createHash('sha256').update(fs.readFileSync(target)).digest('hex');
+}
+
+function sha256Value(value) {
+  return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
+}
+
+function compareByteOrder(left, right) {
+  const leftString = left === null || left === undefined ? '' : String(left);
+  const rightString = right === null || right === undefined ? '' : String(right);
+  if (leftString < rightString) return -1;
+  if (leftString > rightString) return 1;
+  return 0;
+}
+
+function sortedUnique(values) {
+  return [...new Set((Array.isArray(values) ? values : [])
+    .filter((value) => value !== null && value !== undefined && value !== '')
+    .map(String))]
+    .sort(compareByteOrder);
+}
+
+function sortedObject(entries) {
+  return Object.fromEntries(Object.entries(entries).sort(([left], [right]) => (
+    compareByteOrder(left, right)
+  )));
+}
+
+function countBy(items, accessor) {
+  const counts = {};
+  for (const item of Array.isArray(items) ? items : []) {
+    const raw = typeof accessor === 'function' ? accessor(item) : item?.[accessor];
+    const key = raw === null || raw === undefined || raw === '' ? 'none' : String(raw);
+    counts[key] = (counts[key] ?? 0) + 1;
+  }
+  return sortedObject(counts);
+}
+
+function arrayOrEmpty(value) {
+  return Array.isArray(value) ? value : [];
+}
+
+function hasString(value) {
+  return typeof value === 'string' && value.trim().length > 0;
+}
+
+function validatorStatus(validator) {
+  return validator?.validator_status ?? validator?.summary?.validation_status ?? validator?.status ?? 'unknown';
+}
+
+function readJsonInput(root, relPath, role, diagnostics) {
+  try {
+    const target = resolvePath(root, relPath);
+    if (!target) throw new TypeError('root and relPath must be strings');
+    if (!fs.existsSync(target)) {
+      diagnostics.push({
+        code: 'input_artifact_missing',
+        role,
+        path: relPath,
+        severity: 'critical',
+      });
+      return null;
+    }
+    return JSON.parse(fs.readFileSync(target, 'utf8'));
+  } catch (error) {
+    diagnostics.push({
+      code: 'input_artifact_malformed',
+      role,
+      path: relPath,
+      severity: 'critical',
+      reason: error instanceof Error ? error.message : String(error),
+    });
+    return null;
+  }
+}
+
+function sourceArtifactRef(root, relPath, role, payload = undefined) {
+  const exists = Boolean(resolvePath(root, relPath) && fs.existsSync(resolvePath(root, relPath)));
+  return {
+    role,
+    path: relPath,
+    exists,
+    schema_version: isObject(payload) ? (payload.schema_version ?? null) : null,
+    generated_at: isObject(payload) ? (payload.generated_at ?? null) : null,
+    sha256: exists ? sha256File(root, relPath) : null,
+  };
+}
+
+function loadInputs(root, paths) {
+  const diagnostics = [];
+  return {
+    diagnostics,
+    manifest: readJsonInput(root, paths.manifestIn, 'rag_lite_hvy_slice_manifest', diagnostics),
+    acceptedDelta: readJsonInput(root, paths.acceptedDeltaIn, 'accepted_delta', diagnostics),
+    provisionalSafeDelta: readJsonInput(
+      root,
+      paths.provisionalSafeDeltaIn,
+      'provisional_safe_delta',
+      diagnostics,
+    ),
+    ragLiteHvy01Validator: readJsonInput(
+      root,
+      paths.ragLiteHvy01ValidatorIn,
+      'rag_lite_hvy_01_validator',
+      diagnostics,
+    ),
+    evidenceContextPackSchema: readJsonInput(
+      root,
+      paths.evidenceContextPackSchemaIn,
+      'evidence_context_pack_schema',
+      diagnostics,
+    ),
+    evidenceContextPackFixtures: readJsonInput(
+      root,
+      paths.evidenceContextPackFixturesIn,
+      'evidence_context_pack_fixtures',
+      diagnostics,
+    ),
+    ragLiteHvy02Validator: readJsonInput(
+      root,
+      paths.ragLiteHvy02ValidatorIn,
+      'rag_lite_hvy_02_validator',
+      diagnostics,
+    ),
+    retrievalPackets: readJsonInput(
+      root,
+      paths.retrievalPacketsIn,
