+      diagnostics,
+    ),
+    answerPostureFixtures: readJsonInput(
+      root,
+      paths.answerPostureFixturesIn,
+      'rag_lite_hvy_04_answer_posture_fixtures',
+      diagnostics,
+    ),
+    ragLiteHvy04Validator: readJsonInput(
+      root,
+      paths.ragLiteHvy04ValidatorIn,
+      'rag_lite_hvy_04_validator',
+      diagnostics,
+    ),
+    copilotRagPilotFixtures: readJsonInput(
+      root,
+      paths.copilotRagPilotFixturesIn,
+      'rag_lite_hvy_05_copilot_rag_pilot_fixtures',
+      diagnostics,
+    ),
+    ragLiteHvy05Validator: readJsonInput(
+      root,
+      paths.ragLiteHvy05ValidatorIn,
+      'rag_lite_hvy_05_validator',
+      diagnostics,
