+      diagnostics,
+    ),
+    fullCandidateReviewQueue: readJsonInput(
+      root,
+      paths.fullCandidateReviewQueueIn,
+      'full_candidate_review_queue',
+      diagnostics,
+    ),
+    reviewRequiredLayer: readJsonInput(
+      root,
+      paths.reviewRequiredLayerIn,
+      'review_required_layer',
+      diagnostics,
+    ),
+    blockedQuarantinedLayer: readJsonInput(
+      root,
+      paths.blockedQuarantinedLayerIn,
+      'blocked_quarantined_layer',
+      diagnostics,
+    ),
+  };
+}
+
+function statusOf(assertion) {
+  return assertion?.status ??
+    assertion?.layer ??
+    assertion?.promotion_decision ??
+    assertion?.source_status ??
+    assertion?.source_classification_status ??
+    assertion?.classification_status ??
+    'unknown';
+}
+
+function questionIdOf(value) {
+  return value?.question_row_id ??
+    value?.question_id ??
+    value?.question_key ??
+    value?.subject_ref?.question_row_id ??
+    value?.question_ref?.question_id ??
+    null;
+}
+
+function assertionIdOf(value) {
+  return value?.promotion_assertion_id ??
+    value?.assertion_id ??
+    value?.candidate_id ??
+    value?.source_candidate_id ??
+    value?.source_classification_id ??
+    value?.source_blocker_id ??
+    null;
+}
+
+function rawCandidateItems(fullRawCandidateLayer) {
+  return arrayOrEmpty(fullRawCandidateLayer?.rows).flatMap((row, rowIndex) => (
+    arrayOrEmpty(row?.raw_candidates).map((candidate, candidateIndex) => ({
+      source: candidate,
+      question_row_id: questionIdOf(candidate) ?? row?.question_row_id ?? null,
+      source_row_ref: {
+        path: DEFAULT_PATHS.fullRawCandidateLayerIn,
+        json_pointer: `/rows/${rowIndex}/raw_candidates/${candidateIndex}`,
+      },
+    }))
+  ));
+}
+
+function allUniverseRows(fullRawCandidateLayer) {
+  return arrayOrEmpty(fullRawCandidateLayer?.rows)
+    .filter(isObject)
+    .map((row, rowIndex) => ({
+      ...row,
+      source_row_ref: {
+        path: DEFAULT_PATHS.fullRawCandidateLayerIn,
+        json_pointer: `/rows/${rowIndex}`,
+      },
+    }));
+}
+
+function acceptedAssertions(inputs) {
+  return arrayOrEmpty(inputs?.acceptedDelta?.assertions).filter((assertion) => (
+    statusOf(assertion) === 'accepted'
+  ));
+}
+
+function provisionalSafeAssertions(inputs) {
+  return arrayOrEmpty(inputs?.provisionalSafeDelta?.assertions).filter((assertion) => (
+    statusOf(assertion) === 'provisional_safe'
+  ));
+}
+
+function coveredQuestionIds(inputs) {
+  return new Set([...acceptedAssertions(inputs), ...provisionalSafeAssertions(inputs)]
+    .map(questionIdOf)
+    .filter(Boolean));
+}
+
+function baseAuditItem({
+  queueId,
+  sourceStatus,
+  auditStatus,
+  source,
+  questionRowId,
+  sourceRowRef,
+}) {
+  const idSeed = assertionIdOf(source) ?? questionRowId ?? `${queueId}:unknown`;
+  return {
+    audit_item_id: `rag-lite-hvy-06:${queueId}:${idSeed}`,
+    queue_id: queueId,
+    question_row_id: questionRowId ?? null,
+    assertion_id: assertionIdOf(source),
+    status: sourceStatus,
+    audit_status: auditStatus,
+    source_row_ref: sourceRowRef ?? source?.source_row_ref ?? null,
+    blocking: false,
+    answer_fact_eligible: false,
+    runtime_consumption_allowed: false,
+    fallback_behavior: 'question_attempt_available_without_this_semantic_assertion',
+    readiness_posture: 'non_blocking_audit_only',
+  };
+}
+
+function buildAuditQueues({ generatedAt, inputs }) {
+  const rawItems = rawCandidateItems(inputs.fullRawCandidateLayer)
+    .map(({ source, question_row_id: questionRowId, source_row_ref: sourceRowRef }) => (
+      baseAuditItem({
+        queueId: 'raw_candidate_assertions',
+        sourceStatus: 'raw_candidate',
+        auditStatus: 'excluded_raw_candidate',
+        source,
+        questionRowId,
+        sourceRowRef,
+      })
+    ))
+    .sort((left, right) => compareByteOrder(left.audit_item_id, right.audit_item_id));
+
+  const reviewItems = arrayOrEmpty(inputs.reviewRequiredLayer?.assertions)
+    .map((source) => baseAuditItem({
+      queueId: 'review_required_assertions',
+      sourceStatus: 'review_required',
+      auditStatus: 'excluded_review_required',
+      source,
+      questionRowId: questionIdOf(source),
+      sourceRowRef: source?.source_row_ref,
+    }))
+    .sort((left, right) => compareByteOrder(left.audit_item_id, right.audit_item_id));
+
+  const blockedItems = arrayOrEmpty(inputs.blockedQuarantinedLayer?.assertions)
+    .map((source) => baseAuditItem({
+      queueId: 'blocked_quarantined_assertions',
+      sourceStatus: 'blocked_quarantined',
+      auditStatus: 'excluded_blocked_quarantined',
+      source,
+      questionRowId: questionIdOf(source),
+      sourceRowRef: source?.source_row_ref,
+    }))
+    .sort((left, right) => compareByteOrder(left.audit_item_id, right.audit_item_id));
