+  const covered = coveredQuestionIds(inputs);
+  const missingItems = allUniverseRows(inputs.fullRawCandidateLayer)
+    .filter((row) => !covered.has(row.question_row_id))
+    .map((row) => ({
+      audit_item_id: `rag-lite-hvy-06:missing_semantic_coverage:${row.question_row_id}`,
+      queue_id: 'missing_semantic_coverage',
+      question_row_id: row.question_row_id,
+      assertion_id: null,
+      status: 'missing_semantic_kg',
+      audit_status: 'missing_semantic_coverage',
+      source_row_ref: row.source_row_ref,
+      fallback_behavior: 'question_attempt_available_without_semantic_kg',
+      blocking: false,
+      answer_fact_eligible: false,
+      runtime_consumption_allowed: false,
+      readiness_posture: 'non_blocking_audit_only',
+    }))
+    .sort((left, right) => compareByteOrder(left.audit_item_id, right.audit_item_id));
+
+  const auditQueues = [
+    {
+      queue_id: 'raw_candidate_assertions',
+      queue_kind: 'excluded_candidate_assertions',
+      queue_status: 'non_blocking_audit',
+      blocking: false,
+      source_statuses: ['raw_candidate'],
+      items: rawItems,
+    },
+    {
+      queue_id: 'review_required_assertions',
+      queue_kind: 'excluded_review_assertions',
+      queue_status: 'non_blocking_audit',
+      blocking: false,
+      source_statuses: ['review_required'],
+      items: reviewItems,
+    },
+    {
+      queue_id: 'blocked_quarantined_assertions',
+      queue_kind: 'excluded_blocked_assertions',
+      queue_status: 'non_blocking_audit',
+      blocking: false,
+      source_statuses: ['blocked_quarantined'],
+      items: blockedItems,
+    },
+    {
+      queue_id: 'missing_semantic_coverage',
+      queue_kind: 'missing_semantic_coverage',
+      queue_status: 'non_blocking_audit',
+      blocking: false,
+      source_statuses: ['missing_semantic_kg'],
+      items: missingItems,
+    },
+  ];
