+  const allItems = auditQueues.flatMap((queue) => queue.items);
+  const auditQueueArtifact = {
+    schema_version: AUDIT_QUEUES_SCHEMA_VERSION,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    upstream_issues: [...UPSTREAM_ISSUES],
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Publish explicit non-blocking audit queues for semantic KG assertions excluded from RAG-LITE answer facts and rows missing semantic coverage.',
+    queue_policy: {
+      blocking: false,
+      answer_fact_eligible: false,
+      runtime_consumption_allowed: false,
+      question_attempts_remain_available: true,
+      fallback_allowed_sources: [...FALLBACK_ALLOWED_SOURCES],
+      no_invention_constraints: { ...NO_INVENTION_CONSTRAINTS },
+    },
+    summary: {
+      queue_count: auditQueues.length,
+      non_blocking_queue_count: auditQueues.filter((queue) => queue.blocking === false).length,
+      raw_candidate_assertion_count: rawItems.length,
+      review_required_assertion_count: reviewItems.length,
+      blocked_quarantined_assertion_count: blockedItems.length,
+      missing_semantic_coverage_question_count: missingItems.length,
+      answer_fact_eligible_queue_item_count: allItems.filter((item) => (
+        item.answer_fact_eligible === true
+      )).length,
+      runtime_consumption_allowed_queue_item_count: allItems.filter((item) => (
+        item.runtime_consumption_allowed === true
+      )).length,
+      queue_item_count: allItems.length,
+      queue_item_counts: sortedObject(Object.fromEntries(
+        auditQueues.map((queue) => [queue.queue_id, queue.items.length]),
+      )),
+    },
+    audit_queues: auditQueues,
+  };
+  auditQueueArtifact.content_hash = {
+    algorithm: 'sha256',
+    value: sha256Value({
+      ...auditQueueArtifact,
+      content_hash: undefined,
+    }),
+  };
+  return auditQueueArtifact;
+}
+
+function sourceContract(paths) {
+  return {
+    checked_in_artifacts_only: true,
+    rag_input_slice_validator_path: paths.ragLiteHvy01ValidatorIn,
+    evidence_context_pack_schema_validator_path: paths.ragLiteHvy02ValidatorIn,
